<script module lang="ts">
/**
 * A value shown as text, edited in place (`design/components/inline-edit.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/inline-edit.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import { Icon, afterRender, agentMember, joinSlot, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/controls/inline-edit.module.css'
import Button from './Button.svelte'
import Input from './Input.svelte'

export interface InlineEditMessages {
  edit: (label: string) => string
  save: string
  cancel: string
}

export interface InlineEditProps {
  /**
   * The id of a description of the field and the edit control, as SettingsRow's.
   */
  'aria-describedby'?: string
  /**
   * The id of a label elsewhere that names the field, as SettingsRow's row label does.
   */
  'aria-labelledby'?: string
  /**
   * Uncontrolled: whether the field is open when the member mounts. It takes no focus then.
   */
  defaultEditing?: boolean
  /**
   * The edit control is disabled. The value stays as it is.
   */
  disabled?: boolean
  /**
   * Controlled: whether the field is open. The app closes it once a save succeeds.
   */
  editing?: boolean
  /**
   * The app's message for a failed save, drawn under the field while it is open.
   */
  error?: string
  /**
   * Names the field ("Project name") and, through `messages.edit`, the edit control.
   */
  label: string
  maxLength?: number
  /**
   * Omit for the English defaults; localized hosts pass their own.
   */
  messages?: InlineEditMessages
  /**
   * The reader saved a changed text, reported as typed. An uncontrolled field closes at once. A
   * controlled one (`editing`) stays open until the app closes it. Not called for an unchanged
   * text.
   */
  onCommit?: (value: string) => void
  /**
   * The reader opened the field, cancelled, or saved an unchanged text.
   */
  onEditingChange?: (editing: boolean) => void
  /**
   * A save is in flight: the field is read-only, save is busy and cancel is disabled.
   */
  pending?: boolean
  /**
   * Drawn, muted, in place of an empty value, and the empty field's placeholder.
   */
  placeholder?: string
  /**
   * A blank text cannot be saved: the save control is disabled and Enter does nothing.
   */
  required?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * The saved value, drawn as text. The app owns it, so after a save it passes the new value.
   */
  value: string
  /**
   * Another element beside the member draws the value, as a page's `<h1>` does: the member draws
   * its edit control and its field, and the value describes the edit control without being
   * drawn. A page's `titleEdit` sets it.
   */
  valueHidden?: boolean
}
</script>

<script lang="ts">
let {
  'aria-describedby': ariaDescribedbyOwn,
  'aria-labelledby': ariaLabelledbyOwn,
  defaultEditing = false,
  disabled = false,
  editing,
  error,
  label: labelOwn,
  maxLength,
  messages = (() => ({ edit: (label) => `Edit ${label}`, save: 'Save', cancel: 'Cancel' }))(),
  onCommit,
  onEditingChange,
  pending = false,
  placeholder,
  required = false,
  size = 'md',
  value,
  valueHidden: valueHiddenOwn = false,
}: InlineEditProps = $props()
const uid = $props.id()
const joined = joinSlot(undefined, () => ({ disabled: disabled, label: labelOwn, size: size }))
const ariaDescribedby = $derived(
  joined.passed['aria-describedby'] === undefined
    ? ariaDescribedbyOwn
    : (joined.passed['aria-describedby'] as typeof ariaDescribedbyOwn),
)
const ariaLabelledby = $derived(
  joined.passed['aria-labelledby'] === undefined
    ? ariaLabelledbyOwn
    : (joined.passed['aria-labelledby'] as typeof ariaLabelledbyOwn),
)
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
const valueHidden = $derived(
  joined.passed['valueHidden'] === undefined
    ? valueHiddenOwn
    : (joined.passed['valueHidden'] as typeof valueHiddenOwn),
)
// svelte-ignore state_referenced_locally
let mirror = $state(defaultEditing)
// svelte-ignore state_referenced_locally
let draft = $state(value)
let within = $state(false)
let root = $state<HTMLElement | null>(null)
const current = $derived(editing ?? mirror)
const valueId = $derived(`${uid}-value`)
const errorId = $derived(`${uid}-error`)
const refused = $derived(required && draft.trim() === '')
const invalid = $derived(current && error !== undefined && error !== '')
const fieldDescribedBy = $derived(
  [invalid ? errorId : undefined, ariaDescribedby].filter((id) => id !== undefined).join(' ') ||
    undefined,
)
const editDescribedBy = $derived(
  ariaDescribedby === undefined ? valueId : `${valueId} ${ariaDescribedby}`,
)
const setOpen = $derived((next: boolean) => {
  mirror = next
  onEditingChange?.(next)
})
const open = $derived(() => {
  draft = value
  setOpen(true)
})
const cancel = $derived(() => {
  if (!pending) setOpen(false)
})
const commit = $derived(() => {
  if (pending || refused) return
  if (draft === value) {
    setOpen(false)
    return
  }
  onCommit?.(draft)
  if (editing === undefined) setOpen(false)
})
const onKey = $derived((event: KeyboardEvent) => {
  if (event.key === 'Escape') {
    event.preventDefault()
    cancel()
    return
  }
  if (event.key === 'Enter' && event.target instanceof HTMLInputElement && !event.isComposing) {
    event.preventDefault()
    commit()
  }
})
const leave = $derived((event: FocusEvent) => {
  const next = event.relatedTarget
  if (next instanceof Node && !(root?.contains(next) ?? false)) within = false
})
const saveText = $derived((text: string) => {
  if (!current) throw new Error('The field is closed: edit opens it.')
  if (pending) throw new Error('A save is in flight.')
  if (required && text.trim() === '') throw new Error('The field is required.')
  draft = text
  if (text === value) {
    setOpen(false)
    return
  }
  onCommit?.(text)
  if (editing === undefined) setOpen(false)
})
const effect1 = () => {
  current
    ? ((draft = value),
      afterRender(() => {
        const input = root?.querySelector('input')
        input?.focus()
        input?.select()
      }))
    : within && afterRender(() => root?.querySelector('button')?.focus())
}
watchEffect(effect1, { watch: () => current, mount: false })
const effect2 = () => {
  !pending && current && within && root?.querySelector('input')?.focus()
}
watchEffect(effect2, { watch: () => pending, mount: false })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'InlineEdit',
    element: () => root?.querySelector('input') ?? root?.querySelector('button'),
    state: () => ({
      value: value,
      editing: current,
      pending: pending,
      error: invalid ? (error ?? '') : '',
      disabled: disabled,
    }),
    actions: {
      edit: () =>
        (() => {
          if (!current) open()
        })(),
      save: { argument: 'text', run: (value) => saveText(value) },
      cancel: () =>
        (() => {
          if (pending) throw new Error('A save is in flight.')
          if (current) setOpen(false)
        })(),
    },
    withholds: () => root,
  })
  release3 = () => {
    ran()
  }
}
watchEffect(effect3)
onDestroy(() => release3?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }<div
    bind:this={root}
    class={styles.root}
    data-size={size}
    data-disabled={(disabled) ? '' : undefined}
    data-editing={(current) ? '' : undefined}
    data-member="inline-edit"
    onfocusin={() => { within = true }}
    onfocusout={(event) => { leave(event) }}
    >{#if current
      }<div
        class={styles.panel}
        data-inline-edit-part="panel"
        onkeydown={(event) => { onKey(event) }}
        ><div class={styles.row}
          ><div class={styles.field}
            ><Input
              {size}
              value={draft}
              {placeholder}
              {maxLength}
              readOnly={pending}
              {disabled}
              {invalid}
              aria-label={ariaLabelledby === undefined ? label : undefined}
              aria-labelledby={ariaLabelledby}
              aria-describedby={fieldDescribedBy}
              aria-required={required ? true : undefined}
              onChange={(event) => { draft = event }}
          /></div
          ><Button
            variant="soft"
            tone="accent"
            {size}
            iconOnly={true}
            icon="confirm"
            label={messages.save}
            loading={pending}
            disabled={disabled || refused}
            onClick={() => { commit() }}
          /><Button
            variant="ghost"
            tone="neutral"
            {size}
            iconOnly={true}
            icon="close"
            label={messages.cancel}
            disabled={disabled || pending}
            onClick={() => { cancel() }}
        /></div
        ><div aria-live="polite"
          >{#if invalid
            }<p class={styles.error} id={errorId}
              ><span class={styles.glyph}><Icon name="error" size="sm" /></span
              >{error
            }</p
          >{/if
        }</div
      ></div
    >{:else
      }<span
        class={styles.value}
        id={valueId}
        hidden={valueHidden}
        data-placeholder={(value === '') ? '' : undefined}
        >{(value === '' ? placeholder : value) ?? ''
      }</span
      ><Button
        variant="ghost"
        tone="neutral"
        {size}
        iconOnly={true}
        icon="edit"
        label={messages.edit(label)}
        {disabled}
        aria-describedby={editDescribedBy}
        onClick={() => { open() }}
    />{/if
  }</div
>{/if
}{@render joined.end?.()}
